class Solution {
public:
    std::vector<int> maxPoints(std::vector<std::vector<int>>& grid, std::vector<int>& queries) {
        int m = grid.size(), n = grid[0].size(), k = queries.size();
        std::vector<std::pair<int, int>> sorted_q;
        for (int i = 0; i < k; ++i) sorted_q.push_back({queries[i], i});
        std::sort(sorted_q.begin(), sorted_q.end());

        std::priority_queue<std::vector<int>, std::vector<std::vector<int>>, std::greater<std::vector<int>>> pq;
        std::vector<std::vector<bool>> visited(m, std::vector<bool>(n, false));
        pq.push({grid[0][0], 0, 0});
        visited[0][0] = true;

        std::vector<int> ans(k, 0);
        int count = 0;
        int dirs[4][2] = {{-1,0}, {1,0}, {0,-1}, {0,1}};

        for (const auto& q : sorted_q) {
            int q_val = q.first, q_idx = q.second;
            while (!pq.empty() && pq.top()[0] < q_val) {
                auto cur = pq.top();
                pq.pop();
                count++;
                int r = cur[1], c = cur[2];
                for (auto& d : dirs) {
                    int nr = r + d[0], nc = c + d[1];
                    if (nr >= 0 && nr < m && nc >= 0 && nc < n && !visited[nr][nc]) {
                        visited[nr][nc] = true;
                        pq.push({grid[nr][nc], nr, nc});
                    }
                }
            }
            ans[q_idx] = count;
        }
        return ans;
    }
};

class Solution {
    public int[] maxPoints(int[][] grid, int[] queries) {
        int m = grid.length, n = grid[0].length, k = queries.length;
        int[][] sortedQ = new int[k][2];
        for (int i = 0; i < k; i++) {
            sortedQ[i][0] = queries[i];
            sortedQ[i][1] = i;
        }
        java.util.Arrays.sort(sortedQ, (a, b) -> Integer.compare(a[0], b[0]));

        java.util.PriorityQueue<int[]> pq = new java.util.PriorityQueue<>((a, b) -> Integer.compare(a[0], b[0]));
        boolean[][] visited = new boolean[m][n];
        pq.offer(new int[]{grid[0][0], 0, 0});
        visited[0][0] = true;

        int[] ans = new int[k];
        int count = 0;
        int[][] dirs = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

        for (int[] q : sortedQ) {
            int qVal = q[0], qIdx = q[1];
            while (!pq.isEmpty() && pq.peek()[0] < qVal) {
                int[] cur = pq.poll();
                count++;
                int r = cur[1], c = cur[2];
                for (int[] d : dirs) {
                    int nr = r + d[0], nc = c + d[1];
                    if (nr >= 0 && nr < m && nc >= 0 && nc < n && !visited[nr][nc]) {
                        visited[nr][nc] = true;
                        pq.offer(new int[]{grid[nr][nc], nr, nc});
                    }
                }
            }
            ans[qIdx] = count;
        }
        return ans;
    }
}

var maxPoints = function(grid, queries) {
    const m = grid.length, n = grid[0].length, k = queries.length;
    const sortedQ = queries.map((val, idx) => ({ val, idx })).sort((a, b) => a.val - b.val);

    class MinHeap {
        constructor() { this.data = []; }
        push(val) {
            this.data.push(val);
            this.up(this.data.length - 1);
        }
        pop() {
            if (this.data.length === 0) return null;
            const top = this.data[0];
            const bottom = this.data.pop();
            if (this.data.length > 0) {
                this.data[0] = bottom;
                this.down(0);
            }
            return top;
        }
        peek() { return this.data[0]; }
        size() { return this.data.length; }
        up(i) {
            while (i > 0) {
                const p = (i - 1) >> 1;
                if (this.data[i][0] < this.data[p][0]) {
                    [this.data[i], this.data[p]] = [this.data[p], this.data[i]];
                    i = p;
                } else break;
            }
        }
        down(i) {
            const len = this.data.length;
            while ((i << 1) + 1 < len) {
                let left = (i << 1) + 1, right = left + 1, best = i;
                if (left < len && this.data[left][0] < this.data[best][0]) best = left;
                if (right < len && this.data[right][0] < this.data[best][0]) best = right;
                if (best !== i) {
                    [this.data[i], this.data[best]] = [this.data[best], this.data[i]];
                    i = best;
                } else break;
            }
        }
    }

    const pq = new MinHeap();
    const visited = Array.from({ length: m }, () => new Array(n).fill(false));
    pq.push([grid[0][0], 0, 0]);
    visited[0][0] = true;

    const ans = new Array(k).fill(0);
    let count = 0;
    const dirs = [[-1, 0], [1, 0], [0, -1], [0, 1]];

    for (const { val: qVal, idx: qIdx } of sortedQ) {
        while (pq.size() > 0 && pq.peek()[0] < qVal) {
            const [val, r, c] = pq.pop();
            count++;
            for (const [dr, dc] of dirs) {
                const nr = r + dr, nc = c + dc;
                if (nr >= 0 && nr < m && nc >= 0 && nc < n && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    pq.push([grid[nr][nc], nr, nc]);
                }
            }
        }
        ans[qIdx] = count;
    }
    return ans;
};
